from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication with shared memory and register blocking
matmul_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Each thread computes a 2x2 block
    const int TILE_SIZE = 32;
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Block indices
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Starting positions for the tile
    int row_start = by * TILE_SIZE;
    int col_start = bx * TILE_SIZE;

    // Each thread computes 4 values (2x2 block)
    float c00 = 0.0f;
    float c01 = 0.0f;
    float c10 = 0.0f;
    float c11 = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tile from A (each thread loads 4 elements)
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                int a_row = row_start + ty * 2 + i;
                int a_col = t + tx * 2 + j;
                if (a_row < N && a_col < N) {
                    As[ty * 2 + i][tx * 2 + j] = A[a_row * N + a_col];
                } else {
                    As[ty * 2 + i][tx * 2 + j] = 0.0f;
                }

                int b_row = t + ty * 2 + i;
                int b_col = col_start + tx * 2 + j;
                if (b_row < N && b_col < N) {
                    Bs[ty * 2 + i][tx * 2 + j] = B[b_row * N + b_col];
                } else {
                    Bs[ty * 2 + i][tx * 2 + j] = 0.0f;
                }
            }
        }
        __syncthreads();

        // Compute partial sums using register blocking
        for (int k = 0; k < TILE_SIZE; k++) {
            float a0 = As[ty * 2 + 0][k];
            float a1 = As[ty * 2 + 1][k];
            float b0 = Bs[k][tx * 2 + 0];
            float b1 = Bs[k][tx * 2 + 1];

            c00 += a0 * b0;
            c01 += a0 * b1;
            c10 += a1 * b0;
            c11 += a1 * b1;
        }
        __syncthreads();
    }

    // Write results to global memory
    int c_row = row_start + ty * 2;
    int c_col = col_start + tx * 2;

    if (c_row < N && c_col < N) {
        C[c_row * N + c_col] = c00;
    }
    if (c_row < N && c_col + 1 < N) {
        C[c_row * N + c_col + 1] = c01;
    }
    if (c_row + 1 < N && c_col < N) {
        C[(c_row + 1) * N + c_col] = c10;
    }
    if (c_row + 1 < N && c_col + 1 < N) {
        C[(c_row + 1) * N + c_col + 1] = c11;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Block size: 16x16 threads (each computes 2x2 output)
    dim3 blockDim(16, 16);
    // Grid size: each block computes 32x32 elements
    dim3 gridDim((N + 31) / 32, (N + 31) / 32);

    matmul_kernel<<<gridDim, blockDim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

