from torch.utils.cpp_extension import load_inline

# CUDA kernel for matrix multiplication using WMMA API for tensor cores
matmul_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <mma.h>

using namespace nvcuda;

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Warp matrix multiplication configuration
    const int WARP_SIZE = 32;
    const int WMMA_M = 16;
    const int WMMA_N = 16;
    const int WMMA_K = 16;

    // Block and grid dimensions
    const int BLOCK_SIZE = 256;
    const int WARPS_PER_BLOCK = BLOCK_SIZE / WARP_SIZE;

    // Declare the fragments
    wmma::fragment<wmma::matrix_a, WMMA_M, WMMA_N, WMMA_K, wmma::row_major, wmma::accumulate> a_frag;
    wmma::fragment<wmma::matrix_b, WMMA_M, WMMA_N, WMMA_K, wmma::row_major, wmma::accumulate> b_frag;
    wmma::fragment<wmma::accumulator, WMMA_M, WMMA_N, WMMA_K, float> c_frag;

    // Initialize the output fragment to zeros
    wmma::fill_fragment(c_frag, 0.0f);

    // Thread indexing
    int warp_id = threadIdx.x / WARP_SIZE;
    int lane_id = threadIdx.x % WARP_SIZE;

    // Block position
    int block_row = blockIdx.y * WARPS_PER_BLOCK * WMMA_M;
    int block_col = blockIdx.x * WARPS_PER_BLOCK * WMMA_N;

    // Warp position within block
    int warp_row = warp_id / (WARPS_PER_BLOCK / 2) * WMMA_M;
    int warp_col = warp_id % (WARPS_PER_BLOCK / 2) * WMMA_N;

    // Global position
    int row = block_row + warp_row;
    int col = block_col + warp_col;

    // Loop over K dimension
    for (int k = 0; k < N; k += WMMA_K) {
        int a_col = k;
        int b_row = k;

        // Check boundaries
        if (row < N && a_col < N) {
            wmma::load_matrix_sync(a_frag, A + row * N + a_col, N);
        } else {
            wmma::fill_fragment(a_frag, 0.0f);
        }

        if (b_row < N && col < N) {
            wmma::load_matrix_sync(b_frag, B + b_row * N + col, N);
        } else {
            wmma::fill_fragment(b_frag, 0.0f);
        }

        // Perform matrix multiplication
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);
    }

    // Store the result
    if (row < N && col < N) {
        wmma::store_matrix_sync(C + row * N + col, c_frag, N, wmma::mem_row_major);
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    // Block and grid dimensions
    const int BLOCK_SIZE = 256;
    const int WMMA_M = 16;
    const int WMMA_N = 16;
    const int WARPS_PER_BLOCK = BLOCK_SIZE / 32;

    dim3 grid_dim(
        (N + WARPS_PER_BLOCK * WMMA_N - 1) / (WARPS_PER_BLOCK * WMMA_N),
        (N + WARPS_PER_BLOCK * WMMA_M - 1) / (WARPS_PER_BLOCK * WMMA_M),
        1
    );

    dim3 block_dim(BLOCK_SIZE, 1, 1);

    matmul_kernel<<<grid_dim, block_dim>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

